import { describe, expect, it } from "vitest";
import { encodeQr, renderQr } from "./qr.ts";

/** generated by python-qrcode 8 (version=3, ERROR_CORRECT_M, mask_pattern=5, byte mode) */
const REFERENCE_V3_MASK5 = [
  "11111110011101001100101111111",
  "10000010100111101100101000001",
  "10111010111100011001101011101",
  "10111010111000100110001011101",
  "10111010011101000001001011101",
  "10000010000001100100101000001",
  "11111110101010101010101111111",
  "00000000101001001001000000000",
  "10000010101110111110111001110",
  "00010100110110111111110010110",
  "11010010000010011100000110000",
  "00010000000000110001001010000",
  "00011010110001110010011000001",
  "11001000011011110011011010111",
  "01011010011111110110011000100",
  "00001000110111111001101100101",
  "00101011101110111100110000100",
  "10100000110010010001001011111",
  "11100011011111110111100100001",
  "10000101111100100010101010000",
  "10001110101100011100111110111",
  "00000000101111011011100011000",
  "11111110001001111011101011100",
  "10000010010011001000100010010",
  "10111010001001000001111110001",
  "10111010001100010110100100001",
  "10111010010000010011101011010",
  "10000010011101011000001110101",
  "11111110101100011100000001100",
];

const bits = (m: boolean[][]): string[] => m.map((row) => row.map((b) => (b ? "1" : "0")).join(""));

describe("encodeQr", () => {
  it("matches a reference encoder bit for bit (version 3, mask 5)", () => {
    expect(bits(encodeQr("http://192.168.1.42:3777/#pair=123456", { mask: 5 }))).toEqual(REFERENCE_V3_MASK5);
  });

  it("picks the smallest version that fits and refuses past version 10", () => {
    expect(encodeQr("hi").length).toBe(21);
    expect(encodeQr("x".repeat(100)).length).toBe(6 * 4 + 17);
    expect(() => encodeQr("x".repeat(300))).toThrow(/too long/);
  });

  it("renders two modules per line with a quiet zone", () => {
    const m = encodeQr("hi");
    const lines = renderQr(m).split("\n");
    expect(lines).toHaveLength(Math.ceil((21 + 4) / 2));
    expect(lines.every((l) => [...l].length === 25)).toBe(true);
    expect(renderQr(m, { ansi: true })).toContain("\x1b[30;47m");
  });
});
